head.script:
scwin.gVar = {
    "cStyle" : "",
    "cStyleParent" : "",
}


scwin.onpageload = function () {
    // Global DataList 생성 호출 (dlt_bulletData 포함)
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof parent1 !== 'undefined') {
        parent1.remove();
    }

    // 조건 설정
    let cStyle = scwin.gVar["cStyle"];
    cStyle += "width:400px; height:300px; position:relative;"
    let cStyleParent = scwin.gVar["cStyleParent"];


    let properties = {
        style: cStyle,
    };

    let cList = $c.gcm.createCList(properties);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strParent = '';
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strParent += '<xf:group ' + strNameSpace + ' style="background-color:var(--ws-green-100); height: 400px; '+cStyleParent+'">';
    strParent += '</xf:group>';

    scwin.parent1 = await $p.dynamicCreate(
        "parent1",
        "group",
        strParent,
        grp_comp
    );

    // fwBulletChart 은 dlt_bulletData 바인딩이 필요하므로 직접 dynamicCreate (부모 group 기준 위치 이동 확인을 위해 position:relative 반영)
    strTarget += '<w2:fwBulletChart ' + strNameSpace + ' ' + cList + ' chartType="vbullet" ref="data:dlt_bulletData" valueNode="value" targetNode="target"></w2:fwBulletChart>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "fwBulletChart",
        strTarget,
        parent1
    );
}
